import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.Crpw6aS5.js";const n=JSON.parse('{"title":"1978年 · 周期顶部与投资哲学","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1978年.md","filePath":"05_quotes/by-year/1978年.md"}'),r={name:"05_quotes/by-year/1978年.md"};function s(u,e,c,h,_,i){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_1978年-·-周期顶部与投资哲学" tabindex="-1">1978年 · 周期顶部与投资哲学 <a class="header-anchor" href="#_1978年-·-周期顶部与投资哲学" aria-label="Permalink to &quot;1978年 · 周期顶部与投资哲学&quot;">​</a></h1><blockquote><p>无论数据是否重述，1978年都是好年景。扣除资本利得后的营业利润，期初股东投资回报率为19.4%，离我们1972年的记录只差一点点。——巴菲特（48岁）</p></blockquote><p>本页收录1978年致股东信中的经典语录。1978年保险行业处于周期景气顶端，巴菲特整体回报率达到19.4%。这是最值得品味的一封信：巴菲特深入阐述了&quot;低价买少数股权&quot;的投资哲学，以及为什么愿意被动持有优秀公司而不追求控制权。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>无论数据是否重述，1978年都是好年景。扣除资本利得后的营业利润，期初股东投资回报率为19.4%，离我们1972年的记录只差一点点。</p></blockquote><blockquote><p>无论是所有来源带来的25%权益增长，还是1978年19.4%营业收益带来的权益增长，都不可持续。1979年保险周期已经掉头向下，几乎可以肯定今年以净资产回报率衡量的营业收益会下降。</p></blockquote><blockquote><p>我们不担心市场是否会很快给我们认为便宜的证券重新估值。实际上，我们偏爱恰恰相反，因为大多数年份我们都有资金净流入成为净买家。</p></blockquote><blockquote><p>我们政策是集中持仓。我们避免对一家企业或价格兴趣平平的时候买一点点。当我们确信吸引力足够，我们相信值得买入相当数量。</p></blockquote><blockquote><p>SAFECO可能是美国运营最好的大型财产意外险公司。它们承保能力超凡，准备金计提保守，投资政策非常合理。我们用不到1美元买1美元最好公司的股权，而企业交易中平庸公司都要付出超过1美元的价格。</p></blockquote><blockquote><p>我们为什么想要干涉它们的管理政策呢？记录表明它们管理自己业务比我们自己做更好。坐着让别人干活，可能少了一些兴奋和声望，但我们认为这就是接受被动参与优秀管理唯一失去的东西。</p></blockquote><blockquote><p>我们相信没报告的留存收益，最终对我们的好处和分配的部分一样真实。实际上，如果公司能有利可图地运用额外资本，SAFECO的留存收益对股东价值可能超过1美元兑1美元。</p></blockquote><blockquote><p>我们继续在保险组合中找到一小部分真正杰出的企业，通过证券市场的拍卖定价机制，它们的价格比谈判出售中差企业估值还要便宜。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1978年伯克希尔哈撒韦与多元化零售公司合并，对蓝筹印花持股提升到58%，开始合并报表。保险行业处于周期顶部，整体回报率19.4%，非常出色。巴菲特在信中深入阐述了&quot;低价买少数股权&quot;的投资哲学：二级市场上优秀企业的少数股权往往比并购市场上平庸企业卖得还便宜；愿意被动持有优秀公司，不追求控制权；理解留存收益的价值。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1978年-翻译-·-01-letters-1978年-核心总结-·-01-letters-1978年-思维导图" tabindex="-1"><a href="/01_letters/1978年/翻译.html">01_letters/1978年/翻译</a> · <a href="/01_letters/1978年/核心总结.html">01_letters/1978年/核心总结</a> · <a href="/01_letters/1978年/思维导图.html">01_letters/1978年/思维导图</a> <a class="header-anchor" href="#_01-letters-1978年-翻译-·-01-letters-1978年-核心总结-·-01-letters-1978年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1978年/翻译]] · [[→ 核心总结|01_letters/1978年/核心总结]] · [[→ 思维导图|01_letters/1978年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1978年/翻译.html">/01_letters/1978年/翻译</a></li></ul>',21)])])}const b=t(r,[["render",s]]);export{n as __pageData,b as default};
